from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft

FACTS={
"Acoustic Guitar":"Hollow-bodied plucked string instrument; vibrating strings drive the soundboard and air in the body.",
"Bongos":"Pair of small open-bottom hand drums of different sizes; striking the heads produces contrasting pitches.",
"Cello":"Bowed string instrument held upright between the knees; its long strings and large body give a low-rich range.",
"Dulcimer":"Name covers related zithers; a hammered dulcimer uses small beaters on stretched strings, while an Appalachian dulcimer is fretted and usually plucked.",
"Euphonium":"Low brass instrument with valves and a conical bore; buzzing lips start the sound.",
"Flute":"Side-blown woodwind in the concert family; an air jet across the embouchure hole excites the air column.",
"Gong":"Suspended metal percussion disc that vibrates after a mallet strike; size and shape affect pitch and resonance.",
"Harmonica":"Free-reed wind instrument; blowing or drawing air through channels makes metal reeds vibrate.",
"Instrument":"General word for a device used to make or control music; it is a category, not one sound or family.",
"Jaw Harp":"Small lamellophone held at the mouth; a flexible tongue is plucked while the mouth cavity shapes the tone, without biting the reed.",
"Kazoo":"Membrane instrument that changes a hummed voice through a vibrating membrane; blowing silently through it does not create the usual kazoo sound.",
"Lyre":"Ancient-family plucked string instrument with strings stretched from a soundbox to a yoke.",
"Mandolin":"Small plucked string instrument, commonly with four double courses tuned in fifths.",
"Noise Maker":"Broad label for a sound-producing toy or percussion object; exact mechanism depends on the pictured item.",
"Oboe":"Double-reed woodwind; two thin cane blades vibrate together to start its focused tone.",
"Piano":"Keyboard instrument whose keys trigger felt-covered hammers to strike strings in an acoustic piano.",
"Quarter Note":"Rhythmic notation symbol whose duration is one beat in common 4/4 counting; it is a note value, not an instrument.",
"Recorder":"Duct flute with finger holes; a built-in windway directs air to an edge.",
"Saxophone":"Single-reed woodwind, usually metal-bodied; reed vibration starts the sound despite its brass appearance.",
"Tambourine":"Frame percussion instrument with jingles, sometimes with a drumhead; shaking or striking activates different sounds.",
"Udu Drum":"Nigerian clay pot percussion instrument; hands strike the body and opening to create resonant tones.",
"Vibraphone":"Tuned metal-bar percussion instrument with resonator tubes; motor-driven fans can add tremolo on many models.",
"Whistle":"Air blown across an edge or through a fipple creates a high tone; loud whistles should stay away from ears.",
"Xylophone":"Tuned wooden-bar percussion instrument; bars are struck with mallets and arranged by pitch.",
"Yangqin":"Chinese hammered dulcimer; bamboo beaters strike many strings stretched over a trapezoidal soundboard.",
"Zills":"Small finger cymbals used in pairs; metal discs ring when brought together.",
"Accordion":"Free-reed instrument; bellows push or pull air through reeds while buttons or keys select notes.",
"Bell":"Metal idiophone rings when struck or when an internal clapper hits it; shape and size influence pitch.",
"Electric Piano":"Keyboard instrument using electric/electronic tone generation or amplified pickups rather than an acoustic piano soundboard.",
"Fiddle":"A violin played in folk or traditional styles; the instrument is not a separate biological type from violin.",
"Guitar":"Plucked string instrument with fretted neck; acoustic and electric versions amplify string vibration differently.",
"Irish Whistle":"Simple fipple flute, often six-holed, used in Irish traditional music; finger holes change the air-column length.",
"Jingle Bells":"Small bells or clusters that ring when shaken; repeated metal impacts create the jingle.",
"Keyboard":"Musical keyboard is a layout of keys used to control pitches; the sound source may be acoustic, electric, or digital.",
"Lute":"Plucked string instrument family with a neck and resonating body; many historical and regional forms exist.",
"Maracas":"Rattles with loose material inside hollow shells; shaking makes particles strike the walls.",
"Organ":"Keyboard instrument that sustains tones using pipes or electronic sound generation; keys can control more than one rank or voice.",
"Piccolo":"Small transverse flute pitched an octave above the concert flute in standard orchestral use.",
"Rhythm Sticks":"Pair of percussion sticks used to tap rhythmic patterns; safe use means striking sticks or approved surfaces, never people.",
"Ukulele":"Small four-string plucked instrument, commonly tuned with a high G in many soprano/concert setups.",
"Violin":"Smallest standard orchestral bowed string instrument; bow friction or plucking starts string vibration.",
"Xaphoon":"Compact single-reed wind instrument designed to produce a saxophone-like tone through a simple cylindrical body.",
"Clarinet":"Single-reed woodwind with cylindrical bore; covered/open holes and keys change the effective air-column length.",
"Drum":"Membranophone whose stretched head vibrates when struck; drum shape and tension affect tone.",
"Harp":"Plucked string instrument with strings running between soundboard and neck; each string usually supplies a pitch before pedal/lever changes.",
"Note Card":"Learning card that displays a note symbol or musical prompt; it represents music but makes no sound itself.",
"Quena":"Traditional Andean end-blown flute with a notched rim and finger holes.",
"Trumpet":"High brass instrument; buzzing lips feed a cylindrical-to-flared tube while valves redirect air through extra tubing.",
"Wood Block":"Hollow or resonant wooden percussion block; a beater strike produces a short dry tone.",
"Yidaki":"Yolngu name for a traditional northern Australian didgeridoo-type instrument; lip vibration excites a long hollow tube.",
"Zither":"Family of string instruments whose strings stretch across a body without a projecting neck like a guitar.",
"Shaker":"Percussion instrument with loose particles or moving parts that sound when the body is shaken.",
}
ACTIONS={
"Whistle":"Point only; make a tiny air-whistle gesture without producing a loud sound.","Gong":"Air-swing one slow mallet motion; no loud strike near ears.","Rhythm Sticks":"Tap two fingers together softly; never mime hitting another person.","Jaw Harp":"Point to the picture; do not mime putting a metal reed in the mouth.","Kazoo":"Hum softly with closed lips; do not share a real mouthpiece.","Harmonica":"Cup empty hands near the mouth; do not share a real mouth instrument.","Recorder":"Air-finger imaginary holes; no shared mouthpiece.","Irish Whistle":"Air-finger six holes; keep the real whistle quiet and personal.","Yidaki":"Trace one long tube in the air; no forceful blowing exercise.","Zills":"Bring two fingertips together softly like tiny cymbals.",
}
